={{
  {
    "model": "llama-3.3-70b-versatile",
    "response_format": { "type": "json_object" },
    "messages": [
      {
        "role": "system",
        "content": "You are an expert Knowledge Architect for an Obsidian LLM-Wiki system. Your job is to extract, structure, and preserve every nuance, idea, and question from raw transcripts or text.

CRITICAL EXTRACTION RULES:
1. target_folder:
   - 'inbox': Raw, unorganized, rambling, or incomplete thoughts.
   - 'ideas': Software architectures, product concepts, tools, features, or project strategies.
   - 'questions': Standalone research queries, technical friction points, or unresolved bugs.
2. thought_steps: Deconstruct the raw stream of consciousness into sequential logical reasoning steps (minimum 2-4 steps).
3. ideas_for_recall: EXPLICITLY extract every project idea, feature, system concept, or work item mentioned or implied. Include the context so the user can easily recall why they wanted to build or explore it.
4. open_questions: ALWAYS extract or infer 1-3 unresolved questions, friction points, technical edge cases, or potential bottlenecks.
5. wikilinks: Identify key domain concepts, technology stacks, or architectural components to link across Obsidian (e.g., 'Groq API', 'Vector Database', 'n8n Workflow').
6. tags: 2-3 hierarchical tags (e.g., 'ai/pipeline', 'ideas/backend').

Reply ONLY with a valid JSON object matching this schema:
{
  "target_folder": "inbox | ideas | questions",
  "title": "kebab-case-short-title",
  "display_title": "Human Readable Title",
  "executive_hook": "1-2 sentence core insight summary",
  "trigger": "Context, conversation context, or problem that sparked this input",
  "thought_steps": ["Step 1: ...", "Step 2: ..."],
  "ideas_for_recall": ["Idea 1: Short description + recall context", "Idea 2: ..."],
  "open_questions": ["Question 1...", "Question 2..."],
  "wikilinks": ["Concept 1", "Concept 2"],
  "tags": ["category/subcategory"]
}"
      },
      {
        "role": "user",
        "content": "RAW INPUT:
" + ($json.text || $json.message?.text || "")
      }
    ]
  }
}}

parameters.jsCode:
let rawContent = $input.first().json.choices[0].message.content;
rawContent = rawContent.replace(/```json/g, '').replace(/```/g, '').trim();

let data;
try {
  data = JSON.parse(rawContent);
} catch (e) {
  data = {
    target_folder: "inbox",
    title: "unstructured-thought",
    display_title: "Unstructured Thought",
    executive_hook: rawContent.substring(0, 100),
    trigger: "Telegram raw input",
    thought_steps: [rawContent],
    ideas_for_recall: ["Raw input logged—review for actionable concepts."],
    open_questions: ["What are the actionable next steps for this raw input?"],
    wikilinks: [],
    tags: ["inbox/raw"]
  };
}

// Dynamic Folder Routing Mapping
const folderMapping = {
  'inbox': '01 Inbox',
  'ideas': '02 Ideas',
  'questions': '03 Open Questions'
};

const rawFolder = (data.target_folder || 'ideas').toLowerCase();
const folderName = folderMapping[rawFolder] || '02 Ideas';
const noteType = rawFolder === 'questions' ? 'question' : (rawFolder === 'inbox' ? 'raw_note' : 'idea');

const dateStr = new Date().toISOString().split('T')[0];
const sanitizeTitle = (data.title || 'untitled-thought').toLowerCase().replace(/[^a-z0-9-]/g, '-');
const filePath = `${folderName}/${dateStr}-${sanitizeTitle}.md`;

const tagsArray = (data.tags || ['uncategorized']).map(t => `"${t}"`).join(', ');

// Thought Steps Formatting
const thoughtStepsText = (data.thought_steps && data.thought_steps.length > 0)
  ? data.thought_steps.map((s, i) => `- **Step ${i + 1}:** ${s}`).join('\n')
  : '- **Step 1:** Raw input captured and indexed.';

// Ideas for Recall Formatting
const ideasRecallText = (data.ideas_for_recall && data.ideas_for_recall.length > 0)
  ? data.ideas_for_recall.map(i => `- 💡 **${i}**`).join('\n')
  : '- No specific project ideas explicitly detected.';

// Open Questions Formatting (Dataview '- [ ]' task format)
const openQuestionsText = (data.open_questions && data.open_questions.length > 0)
  ? data.open_questions.map(q => `- [ ] ${q}`).join('\n')
  : '- [ ] What are the long-term trade-offs or next steps for this concept?';

// Formatting Wikilinks with explicit folder path and alias
const wikilinksText = (data.wikilinks && data.wikilinks.length > 0)
  ? data.wikilinks.map(w => `- [[04 MOCs/MOC/${w}|${w}]]`).join('\n')
  : '- [[04 MOCs/MOC - Concept Hub|MOC - Concept Hub]]';

const markdown = `---
type: ${noteType}
status: unprocessed
date: ${dateStr}
tags: [${tagsArray}]
spark_trigger: "${(data.trigger || '').replace(/"/g, '\\"')}"
---

# ${data.display_title || 'New Note'}

> [!abstract] Executive Summary
> **${data.executive_hook || 'No executive summary generated.'}**

### 🧠 Thought Trail
${thoughtStepsText}

---

### 💡 Ideas & Work Items for Recall
> [!lightbulb]+ Extracted Concepts
${ideasRecallText}

---

### ❓ Open Questions & Friction
${openQuestionsText}

---

### 🔗 Concept Maps & Wikilinks
${wikilinksText}
`;

const base64Content = Buffer.from(markdown).toString('base64');

return [{
  json: {
    filePath: filePath,
    markdownContent: markdown,
    base64Content: base64Content,
    displayTitle: data.display_title || 'New Note',
    executiveHook: data.executive_hook || '',
    openQuestionsCount: (data.open_questions || []).length,
    ideasCount: (data.ideas_for_recall || []).length,
    chatId: $('Telegram Bot Trigger').first().json.message.chat.id
  }
}];

